import{_ as n,C as e,o as l,c as s,E as a,a2 as d}from"./chunks/framework.DyLyN3RJ.js";const _=JSON.parse('{"title":"因果标签之后：一次归因模块探针能说明什么","description":"","frontmatter":{"title":"因果标签之后：一次归因模块探针能说明什么","article_type":"experiment-report","edition":"research-center","research_question":"因果归因标签需要什么额外证据才能支持因果解释？","summary":"固定版本归因模块可让非空占位链和不存在的端点激活因果标签。12 组合成调用揭示局部接受条件，也保留测量失败与未测量负对照；它们没有测量真实运行中的错误归因率。","sources":["https://arxiv.org/pdf/2610.32285v1","https://github.com/TraceLite-AI/TraceTrial-Bench","https://arxiv.org/html/2503.13657v3"],"date":"2026-11-13","column":"open-source-engineering","category":"daily","pageClass":"runtime-v6-article","item_id":"SIG-20261113-007","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-13-sig-20261113-007-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-11-13-sig-20261113-007.md","filePath":"zh/engineering/2026-11-13-sig-20261113-007.md","lastUpdated":1794573189000}'),o={name:"zh/engineering/2026-11-13-sig-20261113-007.md"};function h(c,t,p,g,b,u){const r=e("ArticleCover"),i=e("ArticleTableScroll");return l(),s("div",null,[a(r,{image:"/assets/covers/daily-2026-11-13-sig-20261113-007-cover.png",kicker:"研究成果",title:"因果标签之后：一次归因模块探针能说明什么",summary:"固定版本归因模块可让非空占位链和不存在的端点激活因果标签。12 组合成调用揭示局部接受条件，也保留测量失败与未测量负对照；它们没有测量真实运行中的错误归因率。",version:"2026-11-13",languageHref:"/en/engineering/2026-11-13-sig-20261113-007",languageLabel:"English"}),a(i,{language:"zh"}),t[0]||(t[0]=d(`<h1 id="因果标签之后-一次归因模块探针能说明什么" tabindex="-1">因果标签之后：一次归因模块探针能说明什么 <a class="header-anchor" href="#因果标签之后-一次归因模块探针能说明什么" aria-label="Permalink to &quot;因果标签之后：一次归因模块探针能说明什么&quot;">​</a></h1><p>两端判据都失败，再放入一个非空字符串，就足以得到“框架导致失败”的输出吗？在本次固定模块的合成调用中，可以。更值得注意的是：候选连接的两个端点都不存在于失败集合时，因果标签仍然激活，而已追踪失败数量为零。这一组合把标签名称与证据状态之间的距离具体暴露出来。</p><p>本文只报告归因模块的局部契约：候选机制链的程序化激活与完成因果核验是两种证据状态。它不报告完整基准复现，不估计真实运行的错误归因率，也不推断调用方一定没有预校验。</p><h2 id="两个失败还没有构成因果链" tabindex="-1">两个失败还没有构成因果链 <a class="header-anchor" href="#两个失败还没有构成因果链" aria-label="Permalink to &quot;两个失败还没有构成因果链&quot;">​</a></h2><p>TraceTrial（框架与智能体双维度评估基准）把任务侧表现与框架侧判据分开，并区分测量装置是否可用。这个区分有价值：任务结果错误不自动说明框架损坏，框架判据为零也不能单独证明它导致了任务失败。论文对传播链提出额外核验要求，包括确认端点、识别中间信息失真、支持事件顺序，以及检查竞争解释。<a href="https://arxiv.org/pdf/2610.32285v1" target="_blank" rel="noreferrer">论文第一版，第 3.5 节、表 5 及附录中的传播链说明</a></p><p>证据的权威来源也因问题而异。环境状态支持实际效果，模型实际收到的原生记录支持它接触的信息；提供方记录只能支持已捕获的结构化声明。整理后的连续序号是展示顺序，不会凭空创造因果顺序。本文据此把“有候选连接”与“连接已经得到证据核验”分开。<a href="https://arxiv.org/pdf/2610.32285v1" target="_blank" rel="noreferrer">论文，第 3 节</a></p><h2 id="固定版本上的局部实验" tabindex="-1">固定版本上的局部实验 <a class="header-anchor" href="#固定版本上的局部实验" aria-label="Permalink to &quot;固定版本上的局部实验&quot;">​</a></h2><p>同日分析阶段使用读取时固定的归因源码提交（见下文固定版本链接），对原始独立模块执行了 12 组合成判据调用。环境为 Python（程序解释器）3.12.9 和 Windows（操作系统）。写作阶段复用已完成结果，没有运行新实验。</p><p>这不是原生轨迹回放：没有执行基准任务，没有读取真实档案、私有判定标准、语义裁判或调用方。完整合成输入、输出、源码哈希及环境见<a href="/joinwell52/assets/evidence/2026-11-13-sig-20261113-007/article-evidence.json">内部探针记录</a>。下表列出全部 12 组调用；“框架导致”等中文是原始输出标签的对应含义，不是本文对真实因果关系的判定。</p><table tabindex="0"><thead><tr><th>合成条件</th><th>模块输出的标签含义</th><th style="text-align:right;">已追踪失败数</th></tr></thead><tbody><tr><td>两层失败，没有连接</td><td>智能体导致</td><td style="text-align:right;">0</td></tr><tr><td>两层失败，链为空串</td><td>智能体导致</td><td style="text-align:right;">0</td></tr><tr><td>两层失败，链只有空白</td><td>智能体导致</td><td style="text-align:right;">0</td></tr><tr><td>两层失败，链为单字符占位串</td><td>框架导致</td><td style="text-align:right;">1</td></tr><tr><td>两层失败，框架连接端点不存在</td><td>框架导致</td><td style="text-align:right;">1</td></tr><tr><td>两层失败，两个连接端点都不存在</td><td>框架导致</td><td style="text-align:right;">0</td></tr><tr><td>两层均通过</td><td>干净运行</td><td style="text-align:right;">0</td></tr><tr><td>仅框架层失败</td><td>框架缺陷被吸收</td><td style="text-align:right;">0</td></tr><tr><td>仅智能体层失败</td><td>智能体导致</td><td style="text-align:right;">0</td></tr><tr><td>测量装置失败，仍提供非空链</td><td>因装置失败而无法判定</td><td style="text-align:right;">0</td></tr><tr><td>框架层没有可测量判据</td><td>因未测量而无法判定</td><td style="text-align:right;">0</td></tr><tr><td>智能体绕过指定观测通道</td><td>智能体导致</td><td style="text-align:right;">0</td></tr></tbody></table><p>预设断言均通过。重要的负对照是空串、空白、测量装置失败和未测量条件：模块并非给任何输入都附上框架因果标签。最后一项也按代码的操作规则处理了被绕过的观测条件，不能直接读成框架自身的内在缺陷。</p><p>核心占位输入可以简写如下；这段仅摘示已执行输入，不是另一次实验：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>failed harness criteria: H1</span></span>
<span class="line"><span>failed agent criteria: A1</span></span>
<span class="line"><span>candidate link: H1 -&gt; A1</span></span>
<span class="line"><span>chain: &quot;x&quot;</span></span>
<span class="line"><span>output attribution: harness_caused</span></span></code></pre></div><p>当连接两端都改为失败集合之外的标识时，输出仍为同一个因果标签，但追踪数量变为零。代码计算追踪数量时检查智能体端点是否位于失败集合；进入联合失败的因果标签分支则只需要仍有被接受的连接。两者的接受条件并不相同。<a href="https://raw.githubusercontent.com/TraceLite-AI/TraceTrial-Bench/98a381307184fa4212db3466b21b4c92a031940b/tracetrial_bench/attribution.py" target="_blank" rel="noreferrer">固定版本归因模块</a></p><h2 id="激活与核验是两种契约" tabindex="-1">激活与核验是两种契约 <a class="header-anchor" href="#激活与核验是两种契约" aria-label="Permalink to &quot;激活与核验是两种契约&quot;">​</a></h2><p>属性 <code>is_substantiated</code>（是否具有实质支撑的属性）在这个模块中检查的是去除首尾空白后，链文本是否非空。这个名字容易让读者联想到“已有实证支撑”，但函数本身没有完成论文描述的端点、失真、顺序与竞争解释审阅。内部探针展示的是该程序谓词的接受范围。</p><p>因此，模块输出的 <code>harness_caused</code>（框架导致标签）应被理解为候选机制链被激活的状态，不能自动升级成“因果核验完成”。论文自己的操作解释也保留了这个区别。局部源码的命名和可执行条件需要一起阅读，不能只相信其中较强的一面。<a href="https://arxiv.org/pdf/2610.32285v1" target="_blank" rel="noreferrer">论文传播链规则</a>；<a href="https://raw.githubusercontent.com/TraceLite-AI/TraceTrial-Bench/98a381307184fa4212db3466b21b4c92a031940b/tracetrial_bench/attribution.py" target="_blank" rel="noreferrer">原始模块实现</a></p><p>这个区别也约束了基准数字的解释。论文报告 95 个任务、9 个模型组和4种框架构成 3,420 个选定实验单元，每个单元保留一次执行，包含替代运行。在 1,700 个双侧未达标运行中，842 个激活了至少一个候选链接，即条件比例 49.5%。这些是来源报告的档案计数，不是本次复跑结果；49.5% 不是因果判断准确率，也不是已经核验的传播率。必需证据选择器没有匹配而得到零分，仍不能单独证明被测系统存在缺陷。<a href="https://arxiv.org/pdf/2610.32285v1" target="_blank" rel="noreferrer">论文，第 4—5 节</a></p><h2 id="调用方的预校验可能改变解释" tabindex="-1">调用方的预校验可能改变解释 <a class="header-anchor" href="#调用方的预校验可能改变解释" aria-label="Permalink to &quot;调用方的预校验可能改变解释&quot;">​</a></h2><p>最有力的替代解释是：这个模块可能有意只接收已核验连接。若调用方已经确认端点和机制链，模块不重复检查未必错误。本次没有审计调用方，也没有检查真实档案中传入的连接，所以合成畸形输入并不建立已经发生的生产故障。</p><p>版本绑定也是边界。读取时的源码提交不等于论文实验冻结版本。论文使用的清单名称与当前仓库说明不同；当前清单中的文档摘要也不同于已读取的第一版论文文件，且清单指向的是另一文件名。因此，字节身份尚未建立；摘要差异本身不能证明任务成员已经变化。本文没有核算最终评分档案，也没有重跑基准。<a href="https://raw.githubusercontent.com/TraceLite-AI/TraceTrial-Bench/98a381307184fa4212db3466b21b4c92a031940b/Task/final.manifest" target="_blank" rel="noreferrer">固定版本任务清单</a></p><p>这些边界不是对论文造假的暗示。论文要求更强的人工审阅，与局部模块采用较窄的输入契约可以同时成立。</p><h2 id="保留证据状态-而不只保留标签" tabindex="-1">保留证据状态，而不只保留标签 <a class="header-anchor" href="#保留证据状态-而不只保留标签" aria-label="Permalink to &quot;保留证据状态，而不只保留标签&quot;">​</a></h2><p>由本次观察支持的接口设计判断是：分别保存判据失败、候选链接、端点核验、中间失真与顺序审阅的状态，并说明由哪一层承担核验。如果只有一个强因果名称，下游读者容易把尚待审阅的候选解释当成已完成判断。缺失证据应保留为缺失，而不是被字段名称遮蔽。</p><p>对实际效果与交互要求也应采用同样的区分。论文的配对案例中，正确的最终值可以与重复执行了仅允许一次的动作同时出现；任务产物正确与交互合规因此需要不同依据。MAST（多智能体系统失败分类研究）所描述的未完成验证、错误验证与过早终止，可以作为定位问题的比较词汇，但它没有独立复现本次模块或验证同一条传播链。<a href="https://arxiv.org/pdf/2610.32285v1" target="_blank" rel="noreferrer">配对案例，论文附录最后部分</a>；<a href="https://arxiv.org/html/2503.13657v3" target="_blank" rel="noreferrer">失败分类研究，第三版</a></p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><ul><li><a href="https://arxiv.org/pdf/2610.32285v1" target="_blank" rel="noreferrer">双维度评估论文，第一版完整文件</a>：作者一手材料，支持证据职责、实验汇总、传播链规则与配对案例；档案数字均保留来源陈述身份。</li><li><a href="https://raw.githubusercontent.com/TraceLite-AI/TraceTrial-Bench/98a381307184fa4212db3466b21b4c92a031940b/tracetrial_bench/attribution.py" target="_blank" rel="noreferrer">归因模块固定版本</a>与<a href="https://raw.githubusercontent.com/TraceLite-AI/TraceTrial-Bench/98a381307184fa4212db3466b21b4c92a031940b/Task/final.manifest" target="_blank" rel="noreferrer">同版本任务清单</a>：支持读取时的实现与绑定观察，未被认定为论文实验冻结版本。</li><li><a href="/joinwell52/assets/evidence/2026-11-13-sig-20261113-007/article-evidence.json">内部探针记录</a>：2026 年 11 月 13 日执行，原始独立模块、12 组合成输入及实际输出，内部实验依据，未获得独立复现。</li><li><a href="https://arxiv.org/html/2503.13657v3" target="_blank" rel="noreferrer">多智能体系统失败分类研究，第三版</a>：来自另一研究团队的背景比较，不是针对本次分类器的独立证据。</li></ul><p>本文把源码事实、作者报告、内部实验与研究解释分开。论文发表不等于验证，引用不等于背书，同行评审不等于证明，作者自报不等于独立证据，局部实现成功也不等于一般有效性。</p><h2 id="真实运行中仍需建立什么证据" tabindex="-1">真实运行中仍需建立什么证据 <a class="header-anchor" href="#真实运行中仍需建立什么证据" aria-label="Permalink to &quot;真实运行中仍需建立什么证据&quot;">​</a></h2><p>本次能够回答模块接受了什么输入，不能回答真实候选链有多少通过了端点、信息失真、事件顺序与竞争解释审阅。下一步需要把选定运行、任务版本、原生轨迹、判定提示和最终评分绑定到同一个实验版本，再检验候选链如何进入归因模块。</p><p>在这项证据出现之前，最稳妥的读法是保留两种状态：程序已经激活了一个解释，因果证据是否足够仍待核验。</p>`,31))])}const m=n(o,[["render",h]]);export{_ as __pageData,m as default};
